const entries = [];
let config = {};
for (const item of items) {
  const j = item.json || {};
  if (j.extraMax !== undefined || j.extraEnabled !== undefined) {
    config = {
      enabled: String(j.extraEnabled || 'true').toLowerCase() === 'true',
      max: Number(j.extraMax || 3),
      threshold: Number(j.extraThreshold || 5),
      minMarketCap: Number(j.extraMinMarketCap || 0),
    };
    continue;
  }
  const symbols = (j.symbols || '').split(',').map(s => s.trim()).filter(Boolean);
  const names = (j.names || '').split(',').map(s => s.trim());
  const category = j.category || 'Unknown';
  const lookback = Number(j.lookback || 3);
  const threshold = Number(j.threshold || 5);
  symbols.forEach((symbol, i) => {
    entries.push({ symbol, name: names[i] || symbol, category, lookback, threshold });
  });
}
const unique = [];
const seen = new Set();
for (const entry of entries) {
  const key = `${entry.category}:${entry.symbol}`;
  if (!seen.has(key)) { seen.add(key); unique.push(entry); }
}
return [{ entries: unique, config }];

const entries = Array.isArray($json.entries) ? $json.entries : [];
const config = $json.config || {};
const listedSymbols = new Set(entries.map(e => e.symbol));
const dropped = [];
const errors = [];

for (const entry of entries) {
  const symbol = entry.symbol;
  const label = entry.name || symbol;
  const category = entry.category || 'Unknown';
  const lookback = Math.max(1, Number(entry.lookback || 3));
  const threshold = Math.max(0, Number(entry.threshold || 5));
  const isCrypto = category.toLowerCase() === 'crypto';
  const rangeDays = isCrypto ? Math.max(lookback + 5, 10) : Math.max((lookback * 3) + 5, 14);
  const url = `https://query1.finance.yahoo.com/v8/finance/chart/${symbol}?range=${rangeDays}d&interval=1d`;

  try {
    const data = await this.helpers.httpRequest({ method: 'GET', url });
    const result = data && data.chart && data.chart.result && data.chart.result[0];
    const closes = (((result || {}).indicators || {}).quote || [])[0] || {};
    const timestamps = (result || {}).timestamp || [];
    const closeArr = closes.close || [];

    const points = [];
    for (let i = 0; i < Math.min(closeArr.length, timestamps.length); i++) {
      const close = closeArr[i];
      const ts = timestamps[i];
      if (typeof close === 'number' && Number.isFinite(close) && close > 0 && typeof ts === 'number') {
        points.push({ close, ts });
      }
    }

    if (points.length < 2) {
      errors.push(`${symbol}: insufficient data`);
      continue;
    }

    const latest = points[points.length - 1];

    // 1d check
    let ref1;
    if (isCrypto) {
      const targetTs = latest.ts - 86400;
      for (let i = points.length - 2; i >= 0; i--) {
        if (points[i].ts <= targetTs) { ref1 = points[i]; break; }
      }
    } else {
      const idx = points.length - 2;
      if (idx >= 0) ref1 = points[idx];
    }

    const change1 = (ref1 && ref1.close > 0)
      ? ((latest.close - ref1.close) / ref1.close) * 100
      : null;

    if (change1 !== null && change1 <= -threshold) {
      dropped.push(`${category} (1d): ${label} ${change1.toFixed(2)}% drop`);
      continue; // 1d already qualifies - skip Nd to avoid duplicate
    }

    // Nd check
    let refN;
    if (isCrypto) {
      const targetTs = latest.ts - (lookback * 86400);
      for (let i = points.length - 2; i >= 0; i--) {
        if (points[i].ts <= targetTs) { refN = points[i]; break; }
      }
    } else {
      const idx = points.length - 1 - lookback;
      if (idx >= 0) refN = points[idx];
    }

    if (!refN || refN.close <= 0) {
      errors.push(`${symbol}: missing reference for ${lookback}d`);
      continue;
    }

    const changeN = ((latest.close - refN.close) / refN.close) * 100;
    if (changeN <= -threshold) {
      dropped.push(`${category} (${lookback}d): ${label} ${changeN.toFixed(2)}% drop`);
    }
  } catch (error) {
    errors.push(`${symbol}: request failed`);
  }
}

// Unlisted symbols: Yahoo day_losers screener, 1d only, limited
const extras = [];
const extraMax = Math.max(0, Number(config.max != null ? config.max : 3));
const extraThreshold = Math.max(0, Number(config.threshold != null ? config.threshold : 5));
const extraMinMarketCap = Math.max(0, Number(config.minMarketCap != null ? config.minMarketCap : 0));
if (config.enabled !== false && extraMax > 0) {
  try {
    const data = await this.helpers.httpRequest({
      method: 'GET',
      url: 'https://query1.finance.yahoo.com/v1/finance/screener/predefined/saved?scrIds=day_losers&count=50',
      headers: { 'User-Agent': 'Mozilla/5.0' },
    });
    const quotes = ((((data || {}).finance || {}).result || [])[0] || {}).quotes || [];
    const candidates = [];
    for (const q of quotes) {
      const symbol = q.symbol;
      const change = q.regularMarketChangePercent;
      if (!symbol || listedSymbols.has(symbol)) continue;
      if (typeof change !== 'number' || !(change <= -extraThreshold)) continue;
      if (q.quoteType !== 'EQUITY' && q.quoteType !== 'ETF') continue;
      if (typeof q.marketCap !== 'number' || !(q.marketCap >= extraMinMarketCap)) continue;
      const cat = q.quoteType === 'ETF' ? 'ETF' : 'Stock';
      const name = q.shortName || q.longName || symbol;
      candidates.push({ cat, name, symbol, change, marketCap: q.marketCap });
    }
    candidates.sort((a, b) => b.marketCap - a.marketCap);
    for (const c of candidates.slice(0, extraMax)) {
      extras.push(`${c.cat} (1d, unlisted): ${c.name} (${c.symbol}) ${c.change.toFixed(2)}% drop`);
    }
  } catch (error) {
    errors.push('screener: request failed');
  }
}

return [{ dropped: dropped.concat(extras), errors }];

